const input = $input.first().json;

// Safaricom Daraja Sandbox credentials
const consumerKey = 'YOUR_DARAJA_CONSUMER_KEY';
const consumerSecret = 'YOUR_DARAJA_CONSUMER_SECRET';
const shortCode = '174379'; // Standard Safaricom sandbox shortcode
const passkey = 'bfb279f9aa9bdbcf158e97dd71a467cd2e0c893059b10f78e6b72ada1ed2c919';

const timestamp = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);
const password = Buffer.from(shortCode + passkey + timestamp).toString('base64');

let phone = String(input.phone_number || '').replace(/[^0-9]/g, '');
if (phone.startsWith('0')) phone = '254' + phone.slice(1);
if (phone.startsWith('7') || phone.startsWith('1')) phone = '254' + phone;

return [{
  json: {
    shortCode,
    password,
    timestamp,
    phone,
    amount: Math.round(Number(input.amount) || 10),
    tenant_id: input.tenant_id,
    order_id: input.order_id || 'ORD_' + Date.now()
  }
}];

const data = $input.first().json;
return [{
  json: {
    status: 'stk_prompt_dispatched',
    phone: data.phone,
    amount: data.amount,
    order_id: data.order_id,
    instructions: 'Please enter your M-Pesa PIN on your phone to complete payment.'
  }
}];
